const $=s=>document.querySelector(s),app=$('#app');
let S=JSON.parse(localStorage.getItem('hrce_session')||'null'),page=location.hash.slice(1)||'dashboard';
const cache=new Map(), pending=new Map();
const api=async(path,opt={})=>{
  const key=opt.method&&opt.method!=='GET'?null:path;
  if(key&&cache.has(key)) return cache.get(key);
  if(key&&pending.has(key)) return pending.get(key);
  const h={'content-type':'application/json',...(opt.headers||{})}; if(S?.token)h.Authorization='Bearer '+S.token;
  const p=fetch(path,{...opt,headers:h}).then(async r=>{
    if(r.status===401){localStorage.removeItem('hrce_session');S=null;login();throw Error('انتهت الجلسة')}
    const d=await r.json().catch(()=>({}));
    if(!r.ok)throw Error(d.error||'حدث خطأ');
    return d;
  });
  if(key)pending.set(key,p);
  try{const d=await p;if(key)cache.set(key,d);return d}finally{if(key)pending.delete(key)}
};
const invalidate=(prefix='')=>{for(const k of cache.keys())if(!prefix||k.startsWith(prefix))cache.delete(k)};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('ar-SA',{minimumFractionDigits:2,maximumFractionDigits:2});
const can=p=>S?.permissions?.includes(p)||S?.user?.role_code==='super_admin';
const icon={dashboard:'⌂',employees:'◉',organization:'⌘',transactions:'⇄',builder:'✦',payroll:'▣',reports:'▤',users:'♙',roles:'⚙',audit:'◷'};
const menu=[['dashboard','لوحة التحكم','dashboard.view'],['employees','الموظفون','employees.view'],['organization','الهيكل التنظيمي','organization.view'],['transactions','المعاملات','transactions.view'],['builder','منشئ المعاملات','transactions.builder'],['payroll','الرواتب','payroll.view'],['reports','التقارير','reports.view'],['users','المستخدمون','users.view'],['roles','الأدوار والصلاحيات','roles.view'],['audit','سجل العمليات','audit.view']];

function login(){
 app.innerHTML=`<div class="login"><div class="login-panel"><div class="brand big"><span>HR</span><div><b>HR Core Enterprise</b><small>نظام الموارد البشرية المؤسسي</small></div></div><h1>تسجيل الدخول</h1><p class="muted">اختر سياق الشركة ثم أدخل بيانات المستخدم.</p><form id="lf"><label>رمز الشركة<input name="company_code" placeholder="ELITE أو GLOBAL" required></label><label>اسم المستخدم<input name="username" autocomplete="username" required></label><label>كلمة المرور<input type="password" name="password" autocomplete="current-password" required></label><button class="btn primary full">تسجيل الدخول</button><div id="le" class="error"></div></form><small class="hint">مدير النظام يستخدم GLOBAL.</small></div></div>`;
 $('#lf').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{S=await api('/api/auth/login',{method:'POST',body:JSON.stringify(b)});localStorage.setItem('hrce_session',JSON.stringify(S));location.hash='dashboard';route()}catch(x){$('#le').textContent=x.message}};
}
function nav(){return menu.filter(x=>can(x[2])).map(x=>`<a class="${page===x[0]?'active':''}" href="#${x[0]}"><span>${icon[x[0]]}</span>${x[1]}</a>`).join('')}
function shell(title,content){
 app.innerHTML=`<div class="layout"><aside><div class="logo"><b>HR</b><div>HR Core<small>Enterprise</small></div></div><div class="nav-title">النظام</div>${nav()}<div class="aside-bottom"><b>${esc(S.user.display_name)}</b><small>${esc(S.user.role_name)}</small><button id="out">تسجيل الخروج</button></div></aside><main><header><div><small>HR Core Enterprise / ${esc(title)}</small><h1>${esc(title)}</h1></div><div class="context">${esc(S.company?.name_ar||'النطاق العام')} <button id="rf" title="تحديث">↻</button></div></header><section>${content}</section></main></div>`;
 document.querySelectorAll('a[href^="#"]').forEach(a=>a.onclick=e=>{e.preventDefault();location.hash=a.getAttribute('href').slice(1);route()});
 $('#out').onclick=async()=>{await api('/api/auth/logout',{method:'POST'}).catch(()=>{});localStorage.removeItem('hrce_session');S=null;login()};
 $('#rf').onclick=()=>{invalidate();route(page)};
}
function table(headers,rows,empty='لا توجد بيانات'){return `<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`}
function modal(title,body,wide=false){const o=document.createElement('div');o.className='modal';o.innerHTML=`<div class="modalbox ${wide?'wide':''}"><div class="head"><h2>${title}</h2><button class="x">×</button></div>${body}</div>`;document.body.append(o);o.querySelector('.x').onclick=()=>o.remove();return o}
async function dashboard(){const d=await api('/api/state');return `<div class="hero"><div><span>مركز التشغيل</span><h2>مرحباً ${esc(S.user.display_name)}</h2><p>بيئة موحدة لإدارة الموظفين والهيكل والمعاملات والرواتب.</p></div><div class="health"><b>● متصل</b><small>Cloudflare D1</small></div></div><div class="stats">${[['الموظفون',d.stats.employees],['المعاملات المفتوحة',d.stats.transactions],['أنواع المعاملات',d.stats.definitions],['الوحدات التنظيمية',d.stats.departments],['المسيرات المفتوحة',d.stats.payroll]].map(x=>`<div class="stat"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div><div class="grid2"><div class="card"><div class="head"><h3>آخر المعاملات</h3><a href="#transactions">عرض الكل</a></div>${table(['الرقم','المعاملة','الموظف','الحالة'],(d.recent||[]).map(x=>`<tr><td>${esc(x.transaction_no)}</td><td>${esc(x.definition_name)}</td><td>${esc(x.employee_name||'-')}</td><td><span class="badge">${esc(x.status)}</span></td></tr>`).join(''))}</div><div class="card"><h3>الوصول السريع</h3><div class="quick">${menu.filter(x=>can(x[2])).slice(0,6).map(x=>`<a href="#${x[0]}"><b>${icon[x[0]]}</b><span>${x[1]}</span></a>`).join('')}</div></div></div>`}
async function employees(){
 const data=await api('/api/employees');const btn=can('employees.create')?`<button class="btn primary" id="add">+ موظف جديد</button>`:'';const rows=data.map(e=>`<tr><td>${esc(e.employee_no)}</td><td><b>${esc(e.name_ar)}</b><small>${esc(e.email||'')}</small></td><td>${esc(e.department_name||'-')}</td><td>${esc(e.position_title||e.job_title||'-')}</td><td>${esc(e.employment_status)}</td><td>${can('employees.salary.view')?money(e.basic_salary):'••••'}</td><td>${can('employees.bank.view')?esc(e.iban||'-'):'••••'}</td></tr>`).join('');
 setTimeout(()=>$('#add')?.addEventListener('click',employeeModal),0);return `<div class="toolbar"><div><h3>سجل الموظفين</h3><p class="muted">Employee Master Record — ${data.length} سجل</p></div>${btn}</div>${table(['الرقم','الموظف','الإدارة','الوظيفة','الحالة','الراتب الأساسي','IBAN'],rows)}`;
}
async function employeeModal(){const o=modal('إضافة موظف',`<form id="ef" class="formgrid">${[['employee_no','رقم الموظف'],['name_ar','الاسم العربي'],['name_en','الاسم الإنجليزي'],['national_id','الهوية / الإقامة'],['nationality','الجنسية'],['email','البريد'],['phone','الجوال'],['hire_date','تاريخ الالتحاق'],['job_title','المسمى الوظيفي'],['work_location','موقع العمل'],['contract_type','نوع العقد'],['basic_salary','الراتب الأساسي'],['housing_allowance','بدل السكن'],['transport_allowance','بدل النقل'],['other_allowances','بدلات أخرى'],['bank_name','البنك'],['iban','IBAN']].map(x=>`<label>${x[1]}<input name="${x[0]}" ${x[0]==='hire_date'?'type=date':''}></label>`).join('')}<div class="form-actions"><button type="button" class="btn cancel">إلغاء</button><button class="btn primary">حفظ</button></div></form>`);
 o.querySelector('.cancel').onclick=()=>o.remove();o.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/employees',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});o.remove();invalidate('/api/');route('employees')}catch(x){alert(x.message)}};
}
function buildTree(depts){
 const byParent=new Map();depts.forEach(d=>{const k=d.parent_id||0;if(!byParent.has(k))byParent.set(k,[]);byParent.get(k).push(d)});
 const node=d=>`<div class="org-node"><div class="org-box"><b>${esc(d.name_ar)}</b><small>${esc(d.code)}${d.manager_name?' · '+esc(d.manager_name):''}</small></div>${(byParent.get(d.id)||[]).length?`<div class="org-children">${(byParent.get(d.id)||[]).map(node).join('')}</div>`:''}</div>`;
 return (byParent.get(0)||[]).map(node).join('')||'<div class="empty">لا توجد وحدات تنظيمية. أنشئ أول وحدة من زر «إضافة وحدة».</div>';
}
async function organization(){
 const d=await api('/api/org');const add=can('organization.manage')?`<button class="btn primary" id="addd">+ وحدة تنظيمية</button>`:'';const addp=can('organization.manage')?`<button class="btn" id="addp">+ وظيفة</button>`:'';
 setTimeout(()=>{$('#addd')?.addEventListener('click',()=>orgModal(d,'department'));$('#addp')?.addEventListener('click',()=>orgModal(d,'position'))},0);
 const pos=d.positions.map(x=>`<tr><td>${esc(x.code)}</td><td><b>${esc(x.title_ar)}</b><small>${esc(x.department_name)}</small></td><td>${x.approved_headcount}</td><td>${d.vacancies.filter(v=>v.position_id===x.id&&v.status==='open').length}</td></tr>`).join('');
 return `<div class="toolbar"><div><h3>الهيكل التنظيمي</h3><p class="muted">شركة ← قطاع/إدارة ← قسم ← وظيفة ← موظف</p></div><div class="actions">${add}${addp}</div></div><div class="org-card card"><div class="org-scroll">${buildTree(d.departments)}</div></div><div class="card" style="margin-top:16px"><div class="head"><h3>الوظائف والمقاعد</h3></div>${table(['الكود','الوظيفة / الوحدة','المعتمد','الشاغر'],pos)}</div>`;
}
async function orgModal(d,type){
 const companies=await api('/api/companies');const superA=S.user.role_code==='super_admin';const o=modal(type==='department'?'إضافة وحدة تنظيمية':'إضافة وظيفة',`<form id="of" class="formgrid">${superA?`<label>الشركة<select name="company_id" id="oc">${companies.map(c=>`<option value="${c.id}">${esc(c.name_ar)} (${esc(c.code)})</option>`).join('')}</select></label>`:''}${type==='department'?`<label>نوع الوحدة<select name="unit_type"><option value="sector">قطاع</option><option value="department">إدارة</option><option value="section">قسم</option><option value="unit">وحدة</option><option value="branch">فرع</option></select></label><label>الكود<input name="code" required></label><label>الاسم العربي<input name="name_ar" required></label><label>الاسم الإنجليزي<input name="name_en"></label><label>الوحدة الأم<select name="parent_id"><option value="">الوحدة العليا</option>${d.departments.map(x=>`<option value="${x.id}">${esc(x.name_ar)}</option>`).join('')}</select></label>`:`<label>الوحدة التنظيمية<select name="department_id" required>${d.departments.map(x=>`<option value="${x.id}">${esc(x.name_ar)}</option>`).join('')}</select></label><label>الكود<input name="code" required></label><label>المسمى العربي<input name="title_ar" required></label><label>المسمى الإنجليزي<input name="title_en"></label><label>الدرجة<input name="grade"></label><label>المستوى<input name="level"></label><label>المقاعد المعتمدة<input name="approved_headcount" type="number" min="1" value="1"></label>`}<div class="form-actions"><button type="button" class="btn cancel">إلغاء</button><button class="btn primary">حفظ</button></div></form>`);
 o.querySelector('.cancel').onclick=()=>o.remove();o.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{await api(type==='department'?'/api/org/departments':'/api/org/positions',{method:'POST',body:JSON.stringify(b)});o.remove();invalidate('/api/');route('organization')}catch(x){alert(x.message)}};
}
let txTimer;
async function transactions(){
 const defs=await api('/api/transaction-definitions');let q='';let data={items:[],total:0};const add=can('transactions.create')?`<button class="btn primary" id="newtx">+ تقديم معاملة</button>`:'';
 const render=async()=>{const box=$('#txresults');if(!box)return;box.innerHTML='<div class="loading">جاري البحث…</div>';data=await api(`/api/transactions?q=${encodeURIComponent(q)}&limit=50`);box.innerHTML=table(['رقم المعاملة','النوع','الموظف','المرحلة','الحالة','التاريخ',''],data.items.map(x=>`<tr><td><button class="link" onclick="txDetails(${x.id})">${esc(x.transaction_no)}</button></td><td>${esc(x.definition_name)}</td><td>${esc(x.employee_name||'-')}<small>${esc(x.employee_no||'')}</small></td><td>${esc(x.current_step_name||'-')}</td><td><span class="badge">${esc(x.status)}</span></td><td>${esc(x.created_at?.slice(0,10))}</td><td>${['pending','submitted','returned'].includes(x.status)&&can('transactions.approve')?`<button class="mini" onclick="txAction(${x.id},'approve')">اعتماد</button>`:''}</td></tr>`).join(''),'لا توجد معاملات مطابقة للبحث')};
 setTimeout(()=>{$('#newtx')?.addEventListener('click',()=>transactionModal(defs));$('#txq')?.addEventListener('input',e=>{q=e.target.value;clearTimeout(txTimer);txTimer=setTimeout(render,280)})},0);
 return `<div class="toolbar"><div><h3>إدارة المعاملات</h3><p class="muted">ابحث برقم المعاملة أو الموظف أو نوع المعاملة.</p></div>${add}</div><div class="searchbar"><input id="txq" placeholder="بحث: رقم المعاملة، اسم الموظف، رقم الموظف، نوع المعاملة"><select id="txstatus"><option value="">كل الحالات</option><option>pending</option><option>submitted</option><option>returned</option><option>completed</option><option>rejected</option></select></div><div class="card" id="txresults">${table(['رقم المعاملة','النوع','الموظف','المرحلة','الحالة','التاريخ',''],'')}</div>`;
}
window.txAction=async(id,action)=>{try{await api('/api/transactions/action',{method:'POST',body:JSON.stringify({id,action})});invalidate('/api/transactions');route('transactions')}catch(e){alert(e.message)}};
window.txDetails=async id=>{try{const d=await api('/api/transactions/'+id);const steps=d.workflow||[];modal('تفاصيل المعاملة',`<div class="detail-grid"><div><span>رقم المعاملة</span><b>${esc(d.transaction.transaction_no)}</b></div><div><span>النوع</span><b>${esc(d.transaction.definition_name)}</b></div><div><span>الموظف</span><b>${esc(d.transaction.employee_name||'-')}</b></div><div><span>الحالة</span><b>${esc(d.transaction.status)}</b></div></div><h3>الدورة المستندية</h3><div class="timeline">${steps.map(s=>`<div class="step ${s.id===d.transaction.current_step_id?'current':''}"><b>${s.step_order}. ${esc(s.name_ar)}</b><small>${esc(s.actor_type||'role')}</small></div>`).join('')}</div><h3>بيانات المعاملة</h3>${table(['الحقل','القيمة'],d.values.map(v=>`<tr><td>${esc(v.label_ar)}</td><td>${esc(v.value_text)}</td></tr>`).join(''))}<h3>سجل الإجراءات</h3>${table(['التاريخ','الإجراء','المستخدم','الحالة'],d.history.map(h=>`<tr><td>${esc(h.created_at)}</td><td>${esc(h.action)}</td><td>${esc(h.display_name||'-')}</td><td>${esc(h.to_status||'-')}</td></tr>`).join(''))}`,true)}catch(e){alert(e.message)}};
async function transactionModal(defs){
 const roles=await api('/api/roles');const companies=await api('/api/companies');const o=modal('تقديم معاملة',`<form id="tf"><label>نوع المعاملة<select name="definition_id">${defs.map(d=>`<option value="${d.id}">${esc(d.name_ar)}</option>`).join('')}</select></label><label>الموضوع<input name="subject"></label><label>ملاحظات<textarea name="notes"></textarea></label><div id="fields" class="formgrid"></div><div class="form-actions"><button type="button" class="btn cancel">إلغاء</button><button class="btn primary">إرسال المعاملة</button></div></form>`,true);
 const render=async()=>{const id=Number(o.querySelector('[name=definition_id]').value);const d=await api('/api/transaction-definitions/'+id);o.querySelector('#fields').innerHTML=(d.fields||[]).map(f=>{let input=f.field_type==='textarea'?`<textarea data-field="${f.id}" ${f.required?'required':''}></textarea>`:f.field_type==='date'?`<input type="date" data-field="${f.id}" ${f.required?'required':''}>`:`<input data-field="${f.id}" ${f.required?'required':''}>`;return `<label>${esc(f.label_ar)}${f.required?' *':''}${input}</label>`}).join('')||'<div class="empty">لا توجد حقول لهذه المعاملة.</div>'};
 o.querySelector('[name=definition_id]').onchange=render;await render();o.querySelector('.cancel').onclick=()=>o.remove();o.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),values={};o.querySelectorAll('[data-field]').forEach(x=>values[x.dataset.field]=x.value);try{const r=await api('/api/transactions',{method:'POST',body:JSON.stringify({definition_id:Number(fd.get('definition_id')),subject:fd.get('subject'),notes:fd.get('notes'),values})});alert('تم إنشاء '+r.transaction_no);o.remove();invalidate('/api/transactions');route('transactions')}catch(x){alert(x.message)}};
}
async function builder(){
 const [defs,roles,companies]=await Promise.all([api('/api/transaction-definitions'),api('/api/roles'),api('/api/companies')]);
 setTimeout(()=>$('#bd')?.addEventListener('click',()=>builderModal(roles,companies)),0);
 return `<div class="toolbar"><div><h3>منشئ المعاملات</h3><p class="muted">عرّف المعاملة، الشركة، الحقول، الصلاحيات، وشجرة الاعتماد ثم انشرها.</p></div><button class="btn primary" id="bd">+ إنشاء نوع معاملة</button></div>${table(['الكود','المعاملة','الشركة','الفئة','الاعتمادات','الحالة'],defs.map(x=>`<tr><td>${esc(x.code)}</td><td><b>${esc(x.name_ar)}</b><small>${esc(x.description||'')}</small></td><td>${esc(x.company_id||'عام')}</td><td>${esc(x.category||'-')}</td><td>${esc(x.workflow_name||'غير معرف')}</td><td><span class="badge">${x.active?'منشورة':'مسودة'}</span></td></tr>`).join(''))}<div class="card simulator"><div class="head"><h3>محاكي المعاملة</h3><span class="badge">Preview</span></div><p class="muted">قبل النشر، يتم تعريف الحقول والمراحل والجهة المعتمدة كبيانات حقيقية في D1.</p></div>`;
}
async function builderModal(roles,companies){
 const o=modal('إنشاء نوع معاملة',`<form id="bf"><div class="wizard"><span class="on">1 التعريف</span><span>2 الحقول</span><span>3 الاعتمادات</span><span>4 النشر</span></div><div class="formgrid"><label>الشركة<select name="company_id">${companies.map(c=>`<option value="${c.id}">${esc(c.name_ar)} (${esc(c.code)})</option>`).join('')}</select></label><label>الكود<input name="code" required></label><label>اسم المعاملة<input name="name_ar" required></label><label>الفئة<input name="category" placeholder="موارد بشرية / مالية / تشغيلية"></label><label class="span2">الوصف<textarea name="description"></textarea></label></div><h3>الحقول</h3><div id="fs"></div><button type="button" class="btn" id="af">+ إضافة حقل</button><h3>سلسلة الاعتماد</h3><div id="ws"></div><button type="button" class="btn" id="aw">+ إضافة مرحلة</button><div class="form-actions"><button type="button" class="btn cancel">إلغاء</button><button class="btn primary">إنشاء ونشر</button></div></form>`,true);
 const addField=()=>{const d=document.createElement('div');d.className='repeat';d.innerHTML=`<input placeholder="Code" data-k required><input placeholder="اسم الحقل بالعربي" data-l required><select data-t><option value="text">نص</option><option value="textarea">نص طويل</option><option value="number">رقم</option><option value="currency">عملة</option><option value="date">تاريخ</option><option value="select">قائمة</option><option value="employee">موظف</option><option value="department">إدارة</option><option value="position">وظيفة</option><option value="attachment">مرفق</option><option value="boolean">نعم/لا</option></select><label class="inlinecheck"><input type="checkbox" data-r> إلزامي</label><button type="button" class="iconbtn remove">×</button>`;d.querySelector('.remove').onclick=()=>d.remove();$('#fs').append(d)};
 const addStep=()=>{const d=document.createElement('div');d.className='repeat';d.innerHTML=`<input placeholder="اسم مرحلة الاعتماد" data-s required><select data-role>${roles.roles.map(r=>`<option value="${r.id}">${esc(r.name_ar)}</option>`).join('')}</select><input placeholder="شرط المرحلة (اختياري)" data-c><label class="inlinecheck"><input type="checkbox" data-final> مرحلة نهائية</label><button type="button" class="iconbtn remove">×</button>`;d.querySelector('.remove').onclick=()=>d.remove();$('#ws').append(d)};
 $('#af').onclick=addField;$('#aw').onclick=addStep;addField();addStep();o.querySelector('.cancel').onclick=()=>o.remove();
 o.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.fields=[...o.querySelectorAll('#fs .repeat')].map((x,i)=>({field_key:x.querySelector('[data-k]').value,label_ar:x.querySelector('[data-l]').value,field_type:x.querySelector('[data-t]').value,required:x.querySelector('[data-r]').checked,sort_order:i}));b.workflow=[...o.querySelectorAll('#ws .repeat')].map((x,i,arr)=>({name_ar:x.querySelector('[data-s]').value,role_id:Number(x.querySelector('[data-role]').value),actor_type:'role',condition_json:x.querySelector('[data-c]').value?{text:x.querySelector('[data-c]').value}:null,actions:['approve','reject','return'],is_final:x.querySelector('[data-final]').checked||i===arr.length-1}));try{await api('/api/transaction-definitions',{method:'POST',body:JSON.stringify(b)});o.remove();invalidate('/api/transaction-definitions');route('builder')}catch(x){alert(x.message)}};
}
async function payroll(){const d=await api('/api/payroll');const create=can('payroll.calculate')?`<button class="btn primary" id="gp">+ إنشاء مسير</button>`:'';setTimeout(()=>$('#gp')?.addEventListener('click',payrollModal),0);return `<div class="toolbar"><div><h3>الرواتب</h3><p class="muted">احتساب من التعويضات الفعالة مع GOSI.</p></div>${create}</div>${table(['المسير','الفترة','الحالة','الموظفون','صافي الرواتب','إجراءات'],d.periods.map(x=>`<tr><td>${esc(x.name_ar)}</td><td>${x.period_start} → ${x.period_end}</td><td><span class="badge">${x.status}</span></td><td>${x.item_count}</td><td>${money(x.total_net)}</td><td>${x.status==='open'&&can('payroll.approve')?`<button class="mini" onclick="payAction(${x.id},'approve')">اعتماد</button>`:''} ${x.status==='approved'&&can('payroll.lock')?`<button class="mini" onclick="payAction(${x.id},'lock')">إقفال</button>`:''} ${can('payroll.export')?`<button class="mini" onclick="downloadPayroll(${x.id})">CSV</button>`:''}</td></tr>`).join(''))}`}
window.payAction=async(id,action)=>{try{await api('/api/payroll',{method:'POST',body:JSON.stringify({id,action})});invalidate('/api/payroll');route('payroll')}catch(e){alert(e.message)}};window.downloadPayroll=async id=>{const r=await fetch('/api/payroll/export?id='+id,{headers:{Authorization:'Bearer '+S.token}});const b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='payroll-'+id+'.csv';a.click();URL.revokeObjectURL(u)};
async function payrollModal(){const o=modal('إنشاء مسير',`<form id="pf"><label>اسم المسير<input name="name_ar" required></label><label>بداية الفترة<input name="period_start" type="date" required></label><label>نهاية الفترة<input name="period_end" type="date" required></label><div class="form-actions"><button type="button" class="btn cancel">إلغاء</button><button class="btn primary">احتساب</button></div></form>`);o.querySelector('.cancel').onclick=()=>o.remove();o.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/payroll',{method:'POST',body:JSON.stringify({action:'generate',...Object.fromEntries(new FormData(e.target))})});o.remove();invalidate('/api/payroll');route('payroll')}catch(x){alert(x.message)}}}
async function reports(){const d=await api('/api/reports');return `<div class="report-grid">${[['حالات الموظفين',d.employees,'employment_status'],['حالات المعاملات',d.transactions,'status'],['التوزيع التنظيمي',d.organization,'name_ar'],['الشواغر',d.vacancies,'status'],['الرواتب',d.payroll,'status']].map(x=>`<div class="card"><h3>${x[0]}</h3>${table(['البيان','العدد'],(x[1]||[]).map(r=>`<tr><td>${esc(r[x[2]])}</td><td>${r.count??r.employees??r.periods??''}</td></tr>`).join(''))}</div>`).join('')}</div>`}
async function users(){const d=await api('/api/users');const add=can('users.manage')?`<button class="btn primary" id="au">+ مستخدم</button>`:'';setTimeout(()=>$('#au')?.addEventListener('click',userModal),0);return `<div class="toolbar"><div><h3>المستخدمون</h3><p class="muted">حسابات الدخول مرتبطة بالأدوار والشركات.</p></div>${add}</div>${table(['المستخدم','الموظف','الدور','الحالة'],d.map(x=>`<tr><td>${esc(x.username)}<small>${esc(x.display_name)}</small></td><td>${esc(x.employee_name||'-')}</td><td>${esc(x.role_name)}</td><td>${x.active?'فعال':'موقوف'}</td></tr>`).join(''))}`}
async function userModal(){const [roles,companies]=await Promise.all([api('/api/roles'),api('/api/companies')]);const o=modal('إنشاء مستخدم',`<form id="uf" class="formgrid"><label>اسم المستخدم<input name="username" required></label><label>الاسم<input name="display_name" required></label><label>كلمة المرور<input name="password" type="password" required></label><label>رقم الموظف<input name="employee_id" type="number"></label><label>الشركة<select name="company_id">${companies.map(c=>`<option value="${c.id}">${esc(c.name_ar)}</option>`).join('')}</select></label><label>الدور<select name="role_id">${roles.roles.map(r=>`<option value="${r.id}">${esc(r.name_ar)}</option>`).join('')}</select></label><div class="form-actions"><button type="button" class="btn cancel">إلغاء</button><button class="btn primary">حفظ</button></div></form>`);o.querySelector('.cancel').onclick=()=>o.remove();o.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});o.remove();invalidate('/api/users');route('users')}catch(x){alert(x.message)}}}
async function roles(){const d=await api('/api/roles');const mods=[...new Set(d.permissions.map(p=>p.module))];return `<div class="toolbar"><div><h3>الأدوار والصلاحيات</h3><p class="muted">مصفوفة صلاحيات قابلة للتوسع. Super Admin يرى جميع الصلاحيات.</p></div></div><div class="perm-matrix"><table><thead><tr><th>الصلاحية</th>${d.roles.map(r=>`<th>${esc(r.name_ar)}</th>`).join('')}</tr></thead><tbody>${mods.map(m=>`<tr class="group"><td colspan="${d.roles.length+1}">${esc(m||'عام')}</td></tr>${d.permissions.filter(p=>p.module===m).map(p=>`<tr><td>${esc(p.name_ar)}<small>${esc(p.code)}</small></td>${d.roles.map(r=>`<td>${d.role_permissions.some(x=>x.role_id===r.id&&x.permission_id===p.id)?'<span class="checkmark">✓</span>':'—'}</td>`).join('')}</tr>`).join('')}`).join('')}</tbody></table></div>`}
async function audit(){const d=await api('/api/audit');return table(['الوقت','المستخدم','الإجراء','الكيان','ID'],d.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.display_name||'-')}</td><td>${esc(x.action)}</td><td>${esc(x.entity_type)}</td><td>${x.entity_id||'-'}</td></tr>`).join(''))}
async function route(p=location.hash.slice(1)||'dashboard'){
 if(!S){login();return} page=p;
 try{const map={dashboard:['لوحة التحكم',dashboard],employees:['الموظفون',employees],organization:['الهيكل التنظيمي',organization],transactions:['المعاملات',transactions],builder:['منشئ المعاملات',builder],payroll:['الرواتب',payroll],reports:['التقارير',reports],users:['المستخدمون',users],roles:['الأدوار والصلاحيات',roles],audit:['سجل العمليات',audit]};if(!map[p]||!can(menu.find(x=>x[0]===p)?.[2]||'dashboard.view')){location.hash='dashboard';p='dashboard'}const [title,fn]=map[p];shell(title,`<div class="loading">جاري تجهيز الشاشة…</div>`);const content=await fn();document.querySelector('main section').innerHTML=content;if(p==='transactions'){const q=document.querySelector('#txq');if(q){q.dispatchEvent(new Event('input'));document.querySelector('#txstatus').onchange=async e=>{const box=$('#txresults');box.innerHTML='<div class="loading">جاري البحث…</div>';const d=await api(`/api/transactions?q=${encodeURIComponent(q.value)}&status=${encodeURIComponent(e.target.value)}&limit=50`);box.innerHTML=table(['رقم المعاملة','النوع','الموظف','المرحلة','الحالة','التاريخ',''],d.items.map(x=>`<tr><td><button class="link" onclick="txDetails(${x.id})">${esc(x.transaction_no)}</button></td><td>${esc(x.definition_name)}</td><td>${esc(x.employee_name||'-')}<small>${esc(x.employee_no||'')}</small></td><td>${esc(x.current_step_name||'-')}</td><td><span class="badge">${esc(x.status)}</span></td><td>${esc(x.created_at?.slice(0,10))}</td><td></td></tr>`).join(''))}}}if(p==='builder')$('#bd')?.click}catch(e){console.error(e);const sec=document.querySelector('main section');if(sec)sec.innerHTML=`<div class="card error"><h3>تعذر تحميل الشاشة</h3><p>${esc(e.message)}</p><button class="btn" onclick="invalidate();route('${p}')">إعادة المحاولة</button></div>`}}
window.addEventListener('hashchange',()=>route());if(S)route();else login();
